const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pl-PL',{style:'currency',currency:'PLN',maximumFractionDigits:0}).format(n/100);
const date=s=>new Intl.DateTimeFormat('pl-PL',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(s+'T12:00:00'));
const range=o=>`${date(o.start_date)} — ${date(o.end_date)}`;
const initials=s=>s.split(' ').map(x=>x[0]).slice(0,2).join('');
const age=(s,at=new Date())=>{const b=new Date(s+'T12:00:00');return at.getFullYear()-b.getFullYear()-((at.getMonth()<b.getMonth()||at.getMonth()===b.getMonth()&&at.getDate()<b.getDate())?1:0)};
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 3a5 5 0 0 1 4 5v2"/>',ticket:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8m-8 4h4"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 2v6m10-6v6M3 11h18"/>',wallet:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M3 9h18m-5 5h5M7 5V3h10v2"/>',logout:'<path d="M9 4H4v16h5m5-15 7 7-7 7m7-7H9"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',check:'<path d="m5 12 4 4L19 6"/>',settings:'<path fill="currentColor" stroke="none" fill-rule="evenodd" d="M19.43 12.98c.04-.32.07-.65.07-.98s-.03-.66-.07-.98l2.11-1.65a.5.5 0 0 0 .12-.64l-2-3.46a.5.5 0 0 0-.61-.22l-2.49 1a7.3 7.3 0 0 0-1.69-.98l-.38-2.65A.49.49 0 0 0 14 2h-4a.49.49 0 0 0-.49.42l-.38 2.65c-.61.25-1.17.58-1.69.98l-2.49-1a.49.49 0 0 0-.61.22l-2 3.46a.5.5 0 0 0 .12.64l2.11 1.65c-.04.32-.07.65-.07.98s.03.66.07.98l-2.11 1.65a.5.5 0 0 0-.12.64l2 3.46c.13.23.4.32.61.22l2.49-1c.52.4 1.08.73 1.69.98l.38 2.65c.03.24.24.42.49.42h4c.25 0 .46-.18.49-.42l.38-2.65c.61-.25 1.17-.58 1.69-.98l2.49 1c.23.09.49 0 .61-.22l2-3.46a.5.5 0 0 0-.12-.64l-2.11-1.65ZM12 15.5a3.5 3.5 0 1 1 0-7 3.5 3.5 0 0 1 0 7Z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',wave:'<path d="M2 9c4-6 6 6 10 0s6 6 10 0M2 16c4-6 6 6 10 0s6 6 10 0"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.45" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.wave}</svg>`;
let state=null,user=null,page='home',authMode='login',installPrompt=null,toastTimer,filter={q:'',place:'',from:'',to:'',category:'',sort:'date'},adminFilters={q:'',offer:'',payment:''};
let layoutPreview=localStorage.getItem('longwave-layout-preview')!=='original';
const previewActive=()=>layoutPreview&&Boolean(user);
const modal=$('#modal');let modalReturn=null;
async function api(path,data,method='POST'){if(window.LONGWAVE_PREVIEW)return window.longwavePreviewApi(path,data,method);const r=await fetch('api/'+path,{method:data===undefined?'GET':method,headers:data===undefined?{}:{'Content-Type':'application/json','X-Longwave':'app'},body:data===undefined?undefined:JSON.stringify(data)});let out;try{out=await r.json()}catch{throw Error('Nie udało się odczytać odpowiedzi serwera.')}if(!r.ok){if(r.status===401&&user){user=null;state=null;closeModal();renderAuth()}throw Error(out.error||'Coś poszło nie tak.')}return out}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
let modalMotion=null,modalVersion=0,navVersion=0;
function openModal(html){modalVersion++;modalMotion?.cancel();if(!modal.open)modalReturn=document.activeElement;$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();modal.scrollTop=0;if(motionOK())modalMotion=modal.animate([{opacity:0,transform:'translateY(22px) scale(.98)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:360,easing:'cubic-bezier(.2,.7,.2,1)'})}
function closeModal(){const version=++modalVersion;modalMotion?.cancel();const finish=()=>{if(version!==modalVersion)return;if(modal.open)modal.close();if(modalReturn?.isConnected)modalReturn.focus()};if(modal.open&&motionOK()){modalMotion=modal.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(16px) scale(.985)'}],{duration:190,easing:'ease-in'});modalMotion.finished.then(finish).catch(()=>{})}else finish()}
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal()});
$('.modal-close').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
function formError(form,msg){form.querySelector('.error-box').textContent=msg}
async function busy(form,fn){const btn=form.querySelector('[type=submit]');btn.disabled=true;formError(form,'');try{await fn()}catch(e){formError(form,e.message)}finally{btn.disabled=false}}
async function load(){state=await api('state');user=state.user}
const status=b=>b.paid>=b.amount?'paid':b.paid>0?'partial':'unpaid';
const statusLabel=b=>({paid:'Opłacono',partial:'Częściowo opłacono',unpaid:'Do opłacenia'}[status(b)]);
const statusPill=b=>`<span class="status ${status(b)}">${statusLabel(b)}</span>`;
function renderAuth(){page='home';document.body.classList.remove('layout-preview');document.body.classList.add('modern-auth');$('#app').innerHTML=`<div class="login-layout"><section class="login-story"><img src="assets/category-camp.webp" alt="Longwave nad wodą"><a class="brand" href="#"><img src="assets/brand.png" alt="LONGWAVE"></a><div><h1>Wasza kolejna<br>wielka przygoda.</h1></div></section><section class="auth-panel" id="main"><div class="auth-inner"><h2>Witaj w Longwave.</h2><p>Obejrzyj aplikację i sprawdź, jak działa.</p><div class="demo-buttons"><button data-demo="client">Panel rodzica</button><button data-demo="admin">Administrator</button></div><p class="auth-note">Wersja demonstracyjna. Używaj danych przykładowych. Zmiany pozostają tylko w Twojej przeglądarce — nie tworzą rzeczywistych rezerwacji.</p></div></section></div>`;$$('[data-demo]').forEach(b=>b.onclick=async()=>{await api('login',{email:b.dataset.demo==='admin'?'admin@longwave.local':'demo@longwave.local'});await load();renderShell();window.scrollTo(0,0)})}
function navItems(){return user.role==='admin'?[['home','home','Pulpit'],['offers','compass','Wydarzenia'],['bookings','ticket','Zapisy'],['clients','people','Klienci']]:[['home','home','Przegląd'],['offers','compass','Odkrywaj'],['bookings','ticket','Moje wyjazdy'],['people','people','Uczestnicy']]}

function motionOK(){return !matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.body.classList.contains('motion-off')}
const waterThemes={home:['coast','Tu zaczyna się','Wasza przygoda.'],offers:['ocean','Złap wiatr.','Wybierz swój kierunek.'],bookings:['category-leaders','Przed Wami','piękne wspomnienia.'],people:['category-camp','Wasza ekipa.','Wspólna przygoda.'],clients:['category-family','Ludzie tworzą','Longwave.']};
function waterOpening(){return `<section class="water-opening" aria-label="Longwave — początek sekcji"><div class="water-opening-art" aria-hidden="true"><img src="assets/coast.webp" alt=""></div><img class="water-logo" src="assets/brand.png" alt="LONGWAVE"><div class="water-opening-copy"><p class="water-claim">Tu zaczyna się<br><em>Wasza przygoda.</em></p><button class="water-enter" type="button" aria-label="Przejdź do treści sekcji">${icon('arrow')}</button></div></section>`}
function updateWaterOpening(){const section=$('.water-opening');if(!section)return;const [photo,line,claim]=waterThemes[page]||waterThemes.home;section.querySelector('.water-opening-art img').src=`assets/${photo}.webp`;section.querySelector('.water-claim').innerHTML=`${line}<br><em>${claim}</em>`;section.dataset.section=page;document.body.classList.toggle('app-admin',user?.role==='admin')}
function photoInterlude(photo,title,sub){return `<aside class="photo-interlude"><img src="assets/${photo}.webp" alt="Woda, wybrzeże i wspólne chwile Longwave" loading="lazy"><div><p>${title}</p><span>${sub}</span></div><span class="photo-interlude-mark" aria-hidden="true">${icon('wave')}</span></aside>`}

function renderShell(){document.body.classList.remove('modern-auth');const nav=navItems();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#home" aria-label="Longwave — przegląd"><img src="assets/brand.png" alt="LONGWAVE"></a><nav aria-label="Menu główne">${nav.map(([id,ic,label])=>`<button class="nav-button ${page===id?'active':''}" data-page="${id}">${icon(ic)}${label}${id==='bookings'?`<span class="nav-count">${state.bookings.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="install-side">${icon('phone')}<span>Longwave zawsze blisko.</span><p>Dodaj aplikację do swojego telefonu.</p><button data-install>Zainstaluj aplikację ↗</button></div><div class="profile"><span class="avatar">${esc(initials(user.name))}</span><div><strong>${esc(user.name.split(' ')[0])}</strong><small>${user.role==='admin'?'Administrator':'Konto rodzica'}</small></div><button data-logout aria-label="Wyloguj">${icon('logout')}</button></div></div></aside><main class="main" id="main">${waterOpening()}<div class="content-sheet" id="section-content"><header class="topbar"><div class="breadcrumb"><small>Twoja przestrzeń /</small><span id="crumb"></span></div><div class="top-actions"><span class="mode-badge">${user.role==='admin'?'Administrator · demo':'Wersja demonstracyjna'}</span><button class="icon-button" data-settings aria-label="Ustawienia aplikacji">${icon('settings')}</button><span class="avatar">${esc(initials(user.name))}</span></div></header><div id="offline" class="offline-banner" ${navigator.onLine?'hidden':''}>Jesteś offline. Połącz się z internetem, aby odczytać zapisy lub zapisać zmiany.</div><div id="page"></div></div></main></div><nav class="mobile-nav" aria-label="Menu mobilne">${nav.map(([id,ic,label])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(ic)}${label}</button>`).join('')}</nav>`;bindShell();renderPage()}
function bindShell(){const skip=$('.water-enter');if(skip)skip.onclick=()=>{$('#section-content').scrollIntoView({behavior:motionOK()?'smooth':'instant',block:'start'})};$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$$('[data-install]').forEach(b=>b.onclick=install);$$('[data-logout]').forEach(b=>b.onclick=logout);$('[data-settings]').onclick=settings;$('.brand').onclick=e=>{e.preventDefault();navigate('home')}}
async function navigate(p){const version=++navVersion,view=$('#page');if(page===p)return;if(motionOK()&&view){view.getAnimations().forEach(a=>a.cancel());const exit=view.animate([{opacity:1,transform:'translateY(0)'},{opacity:0,transform:'translateY(-10px)'}],{duration:160,easing:'ease-in'});try{await exit.finished}catch{}}if(version!==navVersion)return;page=p;renderPage();$$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===p));window.scrollTo({top:0,behavior:'instant'});queueCardParallax()}
function renderPage(){document.body.classList.toggle('coastal-home',previewActive()&&page==='home'&&user.role!=='admin');document.body.classList.toggle('layout-preview',previewActive());let switcher=$('#layout-switch');if(!switcher){switcher=document.createElement('button');switcher.id='layout-switch';switcher.className='layout-switch';switcher.onclick=()=>{layoutPreview=!layoutPreview;localStorage.setItem('longwave-layout-preview',layoutPreview?'editorial':'original');renderPage();window.scrollTo({top:0,behavior:'instant'})};$('.top-actions').prepend(switcher)}switcher.hidden=false;switcher.textContent=layoutPreview?'Wróć do poprzedniego':'Wypróbuj nowy układ';switcher.setAttribute('aria-pressed',String(layoutPreview));updateWaterOpening();$('#crumb').textContent=navItems().find(x=>x[0]===page)?.[2]||'';const admin=user.role==='admin';$('#page').innerHTML=`<div class="page">${page==='home'?(admin?adminHome():clientHome()):page==='offers'?offersPage():page==='people'?peoplePage():page==='bookings'?bookingsPage():clientsPage()}</div>`;bindPage()}
function heading(kicker,title,sub,button=''){return `<div class="page-heading"><div><h1>${title}</h1></div>${button}</div>`}
function stats(items){return `<div class="stats">${items.map(([title,value,ic])=>`<div class="stat glass"><div><small>${title}</small><strong>${value}</strong></div>${icon(ic)}</div>`).join('')}</div>`}
function clientHome(){if(previewActive())return editorialHome();const first=user.name.split(' ')[0],b=state.bookings[0],sum=state.bookings.reduce((n,b)=>n+b.amount-b.paid,0);return heading('TWOJE MAŁE, WIELKIE PLANY.',`Cześć, <span>${esc(first)}.</span>`,'Nowe przygody zaczynają się właśnie tutaj.')+`<div class="intro-grid"><section class="feature"><img src="assets/coast.webp" alt="Wybrzeże Bałtyku"><div class="feature-top"><span></span>${icon('up')}</div><div class="feature-bottom"><div><h2>Mniej ekranu.<br>Więcej <i>przygody.</i></h2></div><button class="btn light" data-go="offers">Znajdź swój camp ${icon('arrow')}</button></div></section><section class="next-trip glass"><div class="card-heading"><h2>${b?'W Waszych planach':'Wasza pierwsza przygoda'}</h2>${icon('ticket')}</div>${b?`<span class="tiny">${esc(b.place.toUpperCase())}</span><h3>${esc(b.title)}</h3><p class="date">${range(b)}</p><div class="member-inline"><span class="avatar">${esc(initials(b.first_name+' '+b.last_name))}</span>${esc(b.first_name+' '+b.last_name)}</div><div class="payment-info"><span>Wpłacono ${money(b.paid)}</span><span>${Math.round(b.paid/b.amount*100)}%</span></div><div class="payment-line"><i style="width:${b.paid/b.amount*100}%"></i></div><button class="btn ghost" data-go="bookings">Zobacz zapis ${icon('arrow')}</button>`:`<h3>Najlepsze wspomnienia są przed Wami.</h3><p class="date">Dodaj uczestnika, wybierz wyjazd i zaplanujcie coś pięknego.</p><button class="btn ghost" data-go="people">Dodaj uczestnika ${icon('plus')}</button>`}</section></div>`+stats([['Uczestnicy',state.participants.length,'people'],['Wasze zapisy',state.bookings.length,'ticket'],['Do opłacenia',money(sum),'wallet']])+`<div class="section-heading"><div><h2>Kierunek: dobra przygoda.</h2></div><button data-go="offers">Cała oferta ↗</button></div><div class="offer-grid">${state.offers.slice(0,3).map(offerCard).join('')}</div>${photoInterlude('ocean','Najlepsze wspomnienia?','Te z wiatrem we włosach.')}<p class="note">Przykładowe oferty sezonu 2026. Wersja demonstracyjna nie obsługuje rzeczywistych rezerwacji.</p>`}
function offerCard(o){if(previewActive())return editorialCard(o);const admin=user.role==='admin';return `<article class="offer-card destination-card"><div class="offer-photo"><img src="${esc(window.previewAsset(o.image))}" alt="${esc(o.place)} — ${esc(o.title)}" loading="lazy"><span class="pill">${esc(o.category||'Camp')}</span><button class="icon-button arrow" data-offer="${o.id}" aria-label="Szczegóły: ${esc(o.title)}">${icon('up')}</button><div class="destination-label"><h3>${esc(o.title.replace(o.place+' · ',''))}</h3><span>${icon('pin')}${esc(o.place)}</span></div></div><div class="offer-info"><div class="offer-meta"><span>${date(o.start_date)}</span><span>·</span><span>${o.age_min}–${o.age_max} lat</span></div><div class="offer-footer"><strong>${money(o.price)} <small>/ osoba</small></strong><button ${admin?`data-edit-offer="${o.id}"`:`data-offer="${o.id}"`}>${admin?'Edytuj':o.available?'Poznaj wyjazd':'Brak miejsc'}</button></div>${admin?`<p class="tiny" style="margin-top:12px">${o.booked} / ${o.capacity} uczestników · ${o.active?'Opublikowane':'Ukryte'}</p>`:''}</div></article>`}
function offersPage(){const admin=user.role==='admin';return heading('ZNALAZŁO SIĘ TWOJE MIEJSCE.',admin?'Wydarzenia.':'Odkrywaj <span>więcej.</span>',admin?'Twórz wyjazdy i zarządzaj ofertą Longwave.':'Wybierz datę, miejsce i swoją następną przygodę.',admin?`<button class="btn" data-add-offer>${icon('plus')} Dodaj wydarzenie</button>`:'')+`<details class="discovery-filter-panel"><summary>${icon('search')} Szukaj i filtruj <span aria-hidden="true">+</span></summary><form class="filters glass" id="offer-filters"><label><span>Szukaj wyjazdu</span><input name="q" value="${esc(filter.q)}" placeholder="Nazwa wyjazdu…" aria-label="Szukaj wyjazdu"></label><label><span>Miejsce</span><select name="place" aria-label="Miejsce"><option value="">Wszystkie miejsca</option>${[...new Set(state.offers.map(o=>o.place))].map(x=>`<option ${filter.place===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><label><span>Kategoria</span><select name="category" aria-label="Kategoria"><option value="">Wszystkie kategorie</option>${['Camp','Wyjazd rodzinny','Event','Program liderski'].map(x=>`<option ${filter.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label><span>Od dnia</span><input type="date" name="from" value="${filter.from}" aria-label="Od dnia"></label><label><span>Do dnia</span><input type="date" name="to" value="${filter.to}" aria-label="Do dnia"></label><label><span>Sortowanie</span><select name="sort" aria-label="Sortowanie"><option value="date" ${filter.sort==='date'?'selected':''}>Najbliższy termin</option><option value="price" ${filter.sort==='price'?'selected':''}>Cena rosnąco</option><option value="place" ${filter.sort==='place'?'selected':''}>Miejsce A–Z</option></select></label><button type="button" class="text-button" id="clear-filters">Wyczyść</button></form></details><div class="discovery-categories" aria-label="Kategorie wyjazdów">${['Wszystkie','Camp','Wyjazd rodzinny','Event','Program liderski'].map(x=>`<button type="button" data-category="${x==='Wszystkie'?'':x}" aria-pressed="${filter.category===(x==='Wszystkie'?'':x)}">${x}</button>`).join('')}</div><div class="discovery-heading"><p class="filter-count" id="filter-count" role="status"></p><span class="swipe-note">Przesuń, by odkryć więcej →</span></div><div id="offer-results" class="offer-grid discovery-rail" aria-label="Wyjazdy"></div>${photoInterlude('ocean','Wybierz swój kierunek.','Reszta zaczyna się nad wodą.')}`}
function updateOffers(){syncFilterLabels();$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===filter.category)));let list=state.offers.filter(o=>(!filter.q||(o.title+' '+o.description).toLowerCase().includes(filter.q.toLowerCase()))&&(!filter.place||o.place===filter.place)&&(!filter.category||o.category===filter.category)&&(!filter.from||o.end_date>=filter.from)&&(!filter.to||o.start_date<=filter.to));if(filter.from&&filter.to&&filter.from>filter.to){$('#filter-count').textContent='Data końcowa nie może być wcześniejsza od początkowej.';list=[]}else $('#filter-count').textContent=`${list.length} propozycji`;list.sort((a,b)=>filter.sort==='price'?a.price-b.price:filter.sort==='place'?a.place.localeCompare(b.place,'pl'):a.start_date.localeCompare(b.start_date));$('#offer-results').innerHTML=list.length?list.map(offerCard).join(''):`<div class="empty glass" style="grid-column:1/-1">${icon('search')}<h2>Jeszcze nie ten kierunek.</h2><p>Zmień filtry, aby znaleźć inne wyjazdy.</p></div>`;bindOfferButtons()}
function peoplePage(){return heading('KAŻDY MA SWOJĄ PRZYGODĘ.','Wasza <span>ekipa.</span>','Dodaj dzieci lub innych uczestników. Wiek obliczymy z daty urodzenia.',`<button class="btn" data-add-person>${icon('plus')} Dodaj uczestnika</button>`)+`<div class="people-grid">${state.participants.map(p=>`<article class="person-card glass"><span class="avatar">${esc(initials(p.first_name+' '+p.last_name))}</span><h3>${esc(p.first_name+' '+p.last_name)}</h3><p>${age(p.birth_date)} lat · ur. ${date(p.birth_date)}</p><div class="falki-balance"><span class="falki-wave" aria-hidden="true">≈</span><div><strong>${p.falki||0}</strong><span>falek</span></div></div><button class="btn reward-cta" data-rewards="${p.id}">Wymień na nagrody ${icon('arrow')}</button><div class="person-foot"><span>${state.bookings.filter(b=>b.participant_id===p.id).length} zapisów</span><button class="text-button" data-person="${p.id}">Edytuj ↗</button></div></article>`).join('')}<button class="add-person" data-add-person>${icon('plus')}<span>Nowa osoba w ekipie</span></button></div>`}
function bookingsPage(){if(user.role==='admin')return heading('WSZYSCY NA POKŁADZIE.','Zapisy i płatności.','Kontroluj listy uczestników i ręcznie zapisuj otrzymane wpłaty.')+adminBookingFilters()+`<div class="table-wrap glass" id="booking-table"></div>`;return heading('WSPOMNIENIA W DRODZE.','Wasze <span>wyjazdy.</span>','Tutaj sprawdzisz, kogo i na jaki obóz zapisałeś.')+(state.bookings.length?state.bookings.map(b=>`<article class="booking-card glass"><img src="${esc(window.previewAsset(b.image))}" alt="${esc(b.place)}"><div><span class="eyebrow muted">ZAPIS LW-${String(b.id).padStart(4,'0')}</span><h3 style="margin-top:8px">${esc(b.title)}</h3><p>${range(b)}</p><div class="member-inline"><span class="avatar">${esc(initials(b.first_name+' '+b.last_name))}</span>${esc(b.first_name+' '+b.last_name)}</div></div><div class="payment-box">${statusPill(b)}<strong>${money(b.amount-b.paid)}</strong><div class="payment-info"><span>Pozostało do wpłaty</span></div><div class="payment-line"><i style="width:${b.paid/b.amount*100}%"></i></div><div class="payment-info"><span>Wpłacono ${money(b.paid)}</span><span>Z ${money(b.amount)}</span></div><button class="text-button" data-booking="${b.id}">Szczegóły zapisu ↗</button></div></article>`).join(''):`<div class="empty glass">${icon('ticket')}<h2>Wasza mapa jest jeszcze pusta.</h2><p>Odkryj ofertę i zapisz wybranego uczestnika na jego pierwszą przygodę.</p><button class="btn" data-go="offers">Odkrywaj wyjazdy ${icon('arrow')}</button></div>`)}
function adminHome(){const total=state.bookings.reduce((n,b)=>n+b.amount,0),paid=state.bookings.reduce((n,b)=>n+b.paid,0);return heading('DOBRZE MIEĆ WSZYSTKO POD RĘKĄ.','Dzień dobry, <span>ekipo.</span>','Oto, co dzieje się w Longwave.',`<button class="btn" data-add-offer>${icon('plus')} Dodaj wydarzenie</button>`)+`<section class="loyalty-banner glass"><div><span class="falki-wave" aria-hidden="true">≈</span><div><h2>Falki za przygody.</h2><p>${state.default_falki} falek za nowy obóz · ${state.redemptions.filter(r=>r.status==='pending').length} nagród do wydania</p></div></div><button class="btn" data-loyalty>Zarządzaj falkami ${icon('arrow')}</button></section>`+stats([['Zapisy uczestników',state.bookings.length,'people'],['Otrzymane wpłaty',money(paid),'wallet'],['Do opłacenia',money(total-paid),'ticket']])+`<div class="admin-grid"><section class="admin-card glass"><div class="card-heading"><h2>Wydarzenia pod kontrolą</h2><span class="tiny">${state.offers.length} wydarzeń</span></div>${state.offers.slice(0,4).map(o=>`<div class="camp-row"><img src="${esc(window.previewAsset(o.image))}" alt=""><div><strong>${esc(o.title)}</strong><small>${date(o.start_date)}</small></div><span>${o.booked} / ${o.capacity}</span><button class="icon-button" data-edit-offer="${o.id}" aria-label="Edytuj ${esc(o.title)}">${icon('up')}</button></div>`).join('')}</section><section class="admin-card glass admin-visual"><h2>Wielkie przygody.<br>Dobrze zorganizowane.</h2><button class="btn light" data-go="bookings">Przejdź do zapisów ${icon('arrow')}</button><div class="orbit"></div></section></div><div class="section-heading"><h2>Ostatnie zapisy</h2><button data-go="bookings">Zobacz wszystkie ↗</button></div><div class="table-wrap glass">${bookingTable(state.bookings.slice(0,5))}</div>`}
function adminBookingFilters(){return `<form class="filters glass" id="booking-filters"><label><span>KLIENT LUB UCZESTNIK</span><input name="q" placeholder="Szukaj po nazwisku…" value="${esc(adminFilters.q)}" aria-label="Klient lub uczestnik"></label><label><span>WYDARZENIE</span><select name="offer" aria-label="Wydarzenie"><option value="">Wszystkie wydarzenia</option>${state.offers.map(o=>`<option value="${o.id}" ${adminFilters.offer==o.id?'selected':''}>${esc(o.title)} · ${date(o.start_date)}</option>`).join('')}</select></label><label><span>PŁATNOŚĆ</span><select name="payment" aria-label="Status płatności"><option value="">Wszystkie statusy</option><option value="unpaid" ${adminFilters.payment==='unpaid'?'selected':''}>Do opłacenia</option><option value="partial" ${adminFilters.payment==='partial'?'selected':''}>Częściowo opłacono</option><option value="paid" ${adminFilters.payment==='paid'?'selected':''}>Opłacono</option></select></label></form>`}
function bookingTable(rows){return `<table class="data-table"><thead><tr><th>Uczestnik / klient</th><th>Wydarzenie</th><th>Płatność</th><th>Wpłacono / całość</th><th>Akcja</th></tr></thead><tbody>${rows.map(b=>`<tr><td><strong>${esc(b.first_name+' '+b.last_name)}</strong><small>${esc(b.client_name)}</small></td><td>${esc(b.title)}<small>${range(b)}</small></td><td>${statusPill(b)}</td><td>${money(b.paid)}<small>z ${money(b.amount)}</small></td><td><button data-payment="${b.id}">Zmień wpłatę ↗</button></td></tr>`).join('')||'<tr><td colspan="5">Brak zapisów spełniających kryteria.</td></tr>'}</tbody></table>`}
function updateBookings(){const q=adminFilters.q.toLowerCase();$('#booking-table').innerHTML=bookingTable(state.bookings.filter(b=>(!q||(b.first_name+' '+b.last_name+' '+b.client_name+' '+b.client_email).toLowerCase().includes(q))&&(!adminFilters.offer||b.offer_id==adminFilters.offer)&&(!adminFilters.payment||status(b)===adminFilters.payment)));bindPaymentButtons()}
function clientsPage(){return heading('SPOŁECZNOŚĆ LONGWAVE.','Klienci.','Konta rodziców, ich uczestnicy i historia zapisów.')+`<div class="filters glass"><label><span>SZUKAJ KLIENTA</span><input id="client-search" placeholder="Imię, nazwisko lub e-mail…" aria-label="Szukaj klienta"></label></div><div class="table-wrap glass" id="client-table"></div>`}
function updateClients(q=''){const rows=state.clients.filter(c=>(c.name+' '+c.email).toLowerCase().includes(q.toLowerCase()));$('#client-table').innerHTML=`<table class="data-table"><thead><tr><th>Klient</th><th>E-mail</th><th>Uczestnicy</th><th>Zapisy</th><th>Akcja</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.email)}</td><td>${c.participants}</td><td>${state.bookings.filter(b=>b.user_id===c.id).length}</td><td><button data-client="${c.id}">Otwórz profil ↗</button></td></tr>`).join('')||'<tr><td colspan="5">Brak klientów.</td></tr>'}</tbody></table>`;$$('[data-client]').forEach(b=>b.onclick=()=>clientDetails(+b.dataset.client))}
function bindPage(){$$('[data-rewards]').forEach(b=>b.onclick=()=>rewardsModal(+b.dataset.rewards));$$('[data-loyalty]').forEach(b=>b.onclick=loyaltyAdmin);const search=$('#editorial-search');if(search)search.onsubmit=async e=>{e.preventDefault();filter.q=new FormData(search).get('q').trim();await navigate('offers');const panel=$('.discovery-filter-panel');panel.open=Boolean(filter.q)};$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$$('[data-add-person]').forEach(b=>b.onclick=()=>personForm());$$('[data-person]').forEach(b=>b.onclick=()=>personForm(+b.dataset.person));$$('[data-add-offer]').forEach(b=>b.onclick=()=>offerForm());$$('[data-booking]').forEach(b=>b.onclick=()=>bookingDetails(+b.dataset.booking));bindOfferButtons();bindPaymentButtons();if(page==='offers'){$$('[data-category]').forEach(b=>b.onclick=()=>{filter.category=b.dataset.category;$('#offer-filters [name=category]').value=filter.category;updateOffers()});$('#offer-filters').onsubmit=e=>e.preventDefault();$('#offer-filters').oninput=e=>{filter=Object.fromEntries(new FormData(e.currentTarget));updateOffers()};$('#clear-filters').onclick=()=>{filter={q:'',place:'',from:'',to:'',category:'',sort:'date'};renderPage()};updateOffers()}if(page==='bookings'&&user.role==='admin'){$('#booking-filters').onsubmit=e=>e.preventDefault();$('#booking-filters').oninput=e=>{adminFilters=Object.fromEntries(new FormData(e.currentTarget));updateBookings()};updateBookings()}if(page==='clients'){updateClients();$('#client-search').oninput=e=>updateClients(e.target.value)}}
function bindOfferButtons(){$$('.editorial-card').forEach(card=>card.onclick=e=>{if(e.target.closest('button,a,input,select'))return;const button=card.querySelector('[data-offer],[data-edit-offer]');if(button)offerDetails(+(button.dataset.offer||button.dataset.editOffer))});$$('[data-offer]').forEach(b=>b.onclick=()=>offerDetails(+b.dataset.offer));$$('[data-edit-offer]').forEach(b=>b.onclick=()=>offerForm(+b.dataset.editOffer))}
function bindPaymentButtons(){$$('[data-payment]').forEach(b=>b.onclick=()=>paymentForm(+b.dataset.payment))}
function offerDetails(id){const o=state.offers.find(x=>x.id===id);openModal(`<div class="destination-detail"><img class="modal-photo" src="${esc(window.previewAsset(o.image))}" alt="${esc(o.title)}"><div class="modal-body"><span class="eyebrow muted">${esc(o.category)} / ${esc(o.place)}</span><h2>${esc(o.title)}</h2><p>${esc(o.description)}</p><div class="detail-specs"><div><small>TERMIN</small><strong>${range(o)}</strong></div><div><small>WIEK NA START</small><strong>${o.age_min}–${o.age_max} lat</strong></div><div><small>KATEGORIA</small><strong>${esc(o.category)}</strong></div></div><div class="detail-price"><div><strong>${money(o.price)}</strong><small>za uczestnika</small></div>${user.role==='admin'?`<button class="btn" id="detail-edit">Edytuj wydarzenie</button>`:`<button class="btn" id="enroll-start" ${o.available?'':'disabled'}>${o.available?'Zapisz uczestnika':'Brak miejsc'} ${icon('arrow')}</button>`}</div><p class="form-note">Wersja demonstracyjna · przykładowa oferta 2026.</p></div></div>`);if(user.role==='admin')$('#detail-edit').onclick=()=>offerForm(id);else $('#enroll-start').onclick=()=>enrollForm(id)}
function personForm(id,after){const p=state.participants.find(x=>x.id===id)||{};openModal(`<div class="modal-body"><h2>${id?'Edytuj uczestnika':'Kto jedzie z nami?'}</h2><p>Wiek obliczymy automatycznie z daty urodzenia.</p><form id="person-form"><div class="form-grid"><label>Imię<input name="first_name" value="${esc(p.first_name)}" required maxlength="70" autocomplete="off"></label><label>Nazwisko<input name="last_name" value="${esc(p.last_name)}" required maxlength="70" autocomplete="off"></label><label class="full">Data urodzenia<input type="date" name="birth_date" value="${esc(p.birth_date)}" max="${new Date().toLocaleDateString('sv')}" required></label></div><p class="error-box" role="alert"></p><div class="form-actions"><button type="button" class="btn ghost" data-close>Anuluj</button><button type="submit" class="btn">${id?'Zapisz zmiany':'Dodaj uczestnika'} ${icon('check')}</button></div></form></div>`);$('[data-close]').onclick=closeModal;$('#person-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await api('participants'+(id?'/'+id:''),Object.fromEntries(new FormData(e.target)),id?'PUT':'POST');await load();renderShell();toast('Uczestnik zapisany.');if(after)enrollForm(after);else closeModal()})}}
function enrollForm(id){const o=state.offers.find(x=>x.id===id);if(!state.participants.length){personForm(null,id);return}openModal(`<div class="modal-body"><h2>Kogo zapisujemy?</h2><p>${esc(o.title)}<br>${range(o)}</p><form id="enroll-form"><div style="margin-top:22px">${state.participants.map(p=>{const years=age(p.birth_date,new Date(o.start_date+'T12:00:00')),booked=state.bookings.some(b=>b.participant_id===p.id&&b.offer_id===id),ok=years>=o.age_min&&years<=o.age_max&&!booked;return `<label class="participant-choice"><input type="radio" name="participant_id" value="${p.id}" required ${ok?'':'disabled'}><span><strong>${esc(p.first_name+' '+p.last_name)}</strong><small>${years} lat na rozpoczęcie obozu${booked?' · Już zapisany':!ok?' · Poza zakresem wieku':''}</small></span></label>`}).join('')}</div><button class="text-button" type="button" id="new-enrollment-person">+ Dodaj nowego uczestnika</button><div class="detail-price"><span>Wartość zapisu</span><strong>${money(o.price)}</strong></div><p class="form-note">Zapis demonstracyjny. Nie pobieramy płatności i nie rezerwujemy rzeczywistego miejsca.</p><p class="error-box" role="alert"></p><div class="form-actions"><button type="submit" class="btn">Potwierdź zapis ${icon('check')}</button></div></form></div>`);$('#new-enrollment-person').onclick=()=>personForm(null,id);$('#enroll-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await api('bookings',{offer_id:id,participant_id:+new FormData(e.target).get('participant_id')});await load();closeModal();page='bookings';renderShell();toast('Uczestnik zapisany. Przygoda czeka!')})}}
function bookingDetails(id){const b=state.bookings.find(x=>x.id===id);openModal(`<div class="modal-body"><span class="eyebrow muted">ZAPIS LW-${String(b.id).padStart(4,'0')}</span><h2>${esc(b.title)}</h2><p>${range(b)}</p><div class="client-summary"><div><small>UCZESTNIK</small><strong style="font-size:17px">${esc(b.first_name+' '+b.last_name)}</strong></div><div><small>STATUS</small>${statusPill(b)}</div><div><small>WPŁACONO</small><strong>${money(b.paid)}</strong></div><div><small>DO OPŁACENIA</small><strong>${money(b.amount-b.paid)}</strong></div></div><p class="form-note">Status wpłaty aktualizuje organizator. W wersji demonstracyjnej nie wykonuj żadnego przelewu.</p><div class="form-actions"><button class="btn" id="booking-payment-details">Szczegóły płatności ${icon('arrow')}</button></div></div>`);$('#booking-payment-details').onclick=()=>transferDetails(id)}
function paymentForm(id){const b=state.bookings.find(x=>x.id===id);openModal(`<div class="modal-body"><span class="eyebrow muted">PŁATNOŚĆ / LW-${String(b.id).padStart(4,'0')}</span><h2>Zaktualizuj wpłatę.</h2><p>${esc(b.first_name+' '+b.last_name)} · ${esc(b.title)}<br>Wartość zapisu: ${money(b.amount)}</p><form id="payment-form"><div class="form-grid"><label class="full">Łączna otrzymana kwota (zł)<input type="number" name="paid" min="0" max="${b.amount/100}" step="0.01" required value="${b.paid/100}"></label></div><button type="button" id="mark-paid" class="text-button">Uzupełnij całą kwotę: ${money(b.amount)}</button><p class="form-note">Wpisz sumę wszystkich otrzymanych wpłat. Status zostanie wyliczony automatycznie.</p><p class="error-box" role="alert"></p><div class="form-actions"><button type="submit" class="btn">Zapisz wpłatę ${icon('check')}</button></div></form></div>`);$('#mark-paid').onclick=()=>$('#payment-form [name=paid]').value=b.amount/100;$('#payment-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await api('admin/bookings/'+id,{paid:Math.round(Number(new FormData(e.target).get('paid'))*100)},'PUT');await load();closeModal();renderShell();toast('Wpłata została zaktualizowana.')})}}
function offerForm(id){const o=state.offers.find(x=>x.id===id)||{age_min:7,age_max:15,capacity:30,price:299000,image:'category-camp',active:1,category:'Camp',falki:state.default_falki};openModal(`<div class="modal-body"><h2>${id?'Edytuj wydarzenie.':'Nowa przygoda.'}</h2><p>Dodaj podstawowe informacje. Limit miejsc jest widoczny tylko w panelu administratora.</p><form id="offer-form"><div class="cover-upload"><img id="cover-preview" src="${esc(window.previewAsset(o.image))}" alt="Podgląd okładki"><label>${icon('plus')} Wgraj okładkę<input type="file" id="cover-file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG lub WebP · do 5 MB</small></label></div><div class="form-grid"><label class="full">Nazwa wydarzenia<input name="title" required minlength="3" maxlength="100" value="${esc(o.title)}" placeholder="Np. Jastarnia · Longwave Camp"></label><label>Miejsce<input name="place" list="places" required maxlength="80" value="${esc(o.place)}" placeholder="Wybierz lub wpisz"><datalist id="places"><option>Jastarnia</option><option>Dąbki</option></datalist></label><label>Kategoria<select name="category">${['Camp','Wyjazd rodzinny','Event','Program liderski'].map(x=>`<option ${o.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Data od<input type="date" name="start_date" required value="${esc(o.start_date)}"></label><label>Data do<input type="date" name="end_date" required value="${esc(o.end_date)}"></label><label>Cena za osobę (zł)<input type="number" name="price" min="1" step="0.01" required value="${o.price/100}"></label><label>Maks. liczba uczestników<input type="number" name="capacity" min="${o.booked||1}" max="1000" required value="${o.capacity}"></label><label>Wiek od (lat)<input type="number" name="age_min" min="1" max="99" required value="${o.age_min}"></label><label>Wiek do (lat)<input type="number" name="age_max" min="1" max="99" required value="${o.age_max}"></label><label class="full">Falki za opłacony obóz<input type="number" name="falki" min="0" max="10000" required value="${o.falki??50}"></label><label class="full">Opis wydarzenia<textarea name="description" required maxlength="3000">${esc(o.description)}</textarea></label><label class="full">Widoczność<select name="active"><option value="1" ${o.active?'selected':''}>Opublikowane — widoczne dla klientów</option><option value="0" ${!o.active?'selected':''}>Ukryte — tylko administrator</option></select></label></div><p class="form-note">${id?'Zmiana ceny dotyczy nowych zapisów. Dotychczasowe zachowują swoją cenę.':'Po osiągnięciu limitu aplikacja zablokuje nowe zapisy.'}</p><p class="error-box" role="alert"></p><div class="form-actions"><button type="button" class="btn ghost" data-close>Anuluj</button><button type="submit" class="btn">${id?'Zapisz zmiany':'Dodaj wydarzenie'} ${icon('check')}</button></div></form></div>`);let cover=o.image,pendingFile=null,objectUrl;$('#cover-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>5000000){formError($('#offer-form'),'Zdjęcie może mieć maksymalnie 5 MB.');e.target.value='';return}pendingFile=f;if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(f);$('#cover-preview').src=objectUrl;formError($('#offer-form'),'')};$('[data-close]').onclick=closeModal;$('#offer-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const d=Object.fromEntries(new FormData(e.target));if(d.start_date>=d.end_date)throw Error('Data końcowa musi być późniejsza od początkowej.');if(+d.age_min>+d.age_max)throw Error('Sprawdź zakres wieku.');if(pendingFile){const bytes=new Uint8Array(await pendingFile.arrayBuffer());let bin='';for(const b of bytes)bin+=String.fromCharCode(b);cover=(await api('admin/cover',{data:btoa(bin)})).image}await api('admin/offers'+(id?'/'+id:''),{...d,image:cover,price:Math.round(Number(d.price)*100),active:d.active==='1'},id?'PUT':'POST');if(objectUrl)URL.revokeObjectURL(objectUrl);await load();closeModal();page='offers';renderShell();toast(id?'Zmiany zapisane.':'Nowe wydarzenie jest gotowe.')})}}
function clientDetails(id){const c=state.clients.find(x=>x.id===id),ps=state.participants.filter(p=>p.user_id===id),bs=state.bookings.filter(b=>b.user_id===id);openModal(`<div class="modal-body"><h2>${esc(c.name)}</h2><p>${esc(c.email)}</p><div class="section-heading"><h2>Uczestnicy</h2></div>${ps.map(p=>`<div class="camp-row"><span class="avatar">${esc(initials(p.first_name+' '+p.last_name))}</span><div><strong>${esc(p.first_name+' '+p.last_name)}</strong><small>${age(p.birth_date)} lat · ${date(p.birth_date)} · ${p.falki||0} falek</small></div></div>`).join('')||'<p class="muted">Brak uczestników.</p>'}<div class="section-heading"><h2>Zapisy (${bs.length})</h2></div>${bs.map(b=>`<div class="camp-row"><div><strong>${esc(b.title)}</strong><small>${esc(b.first_name)} · ${range(b)}</small></div>${statusPill(b)}</div>`).join('')||'<p class="muted">Brak zapisów.</p>'}</div>`)}
async function logout(){try{await api('logout',{});user=null;state=null;closeModal();renderAuth();toast('Do zobaczenia nad wodą.')}catch(e){toast(e.message)}}
function settings(){openModal(`<div class="modal-body"><h2>Po Twojemu.</h2><p>${esc(user.name)} · ${esc(user.email)}</p><div class="settings-actions"><button class="btn ghost" id="motion-setting">${document.body.classList.contains('motion-off')?'Włącz animacje':'Ogranicz animacje'}</button><button class="btn ghost" data-install>${icon('phone')} Zainstaluj aplikację</button><button class="btn" data-logout>${icon('logout')} Wyloguj się</button></div><p class="form-note">Podgląd dla klienta. Zmiany zapisują się tylko w tej przeglądarce. Używaj wyłącznie danych przykładowych.</p></div>`);$('#motion-setting').onclick=e=>{document.body.classList.toggle('motion-off');localStorage.setItem('longwave-motion-off',document.body.classList.contains('motion-off'));updateWaterScroll();e.target.textContent=document.body.classList.contains('motion-off')?'Włącz animacje':'Ogranicz animacje'};$$('[data-install]').forEach(b=>b.onclick=install);$$('[data-logout]').forEach(b=>b.onclick=logout)}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null;return}openModal(`<div class="modal-body"><h2>Zawsze pod ręką.</h2><p>Dodaj Longwave do ekranu głównego telefonu:</p><ol class="install-steps"><li><strong>iPhone / Safari:</strong> Udostępnij → Do ekranu początkowego.</li><li><strong>Android / Chrome:</strong> menu przeglądarki → Zainstaluj aplikację lub Dodaj do ekranu głównego.</li></ol><p class="form-note">Instalacja wymaga adresu HTTPS. Zapisy i dane uczestników wymagają połączenia z internetem.</p></div>`)}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('offline',()=>{if($('#offline'))$('#offline').hidden=false});window.addEventListener('online',()=>{if($('#offline'))$('#offline').hidden=true});
if(localStorage.getItem('longwave-motion-off')==='true')document.body.classList.add('motion-off');
if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
(async()=>{try{const session=await api('session');user=session.user;if(user){await load();renderShell()}else renderAuth()}catch{$('#app').innerHTML='<div class="empty"><h1>Chwila bez połączenia.</h1><p>Połącz się z serwerem Longwave i odśwież aplikację. Prywatne dane nie są przechowywane w pamięci offline.</p><button class="btn" id="retry">Spróbuj ponownie</button></div>';$('#retry').onclick=()=>location.reload()}})();

let waterFrame=false;
function updateWaterScroll(){waterFrame=false;const art=$('.water-opening-art');if(!art)return;const section=$('.water-opening');const rect=section.getBoundingClientRect();if(!motionOK()){art.style.transform='';return}if(rect.bottom>0&&rect.top<innerHeight){const travel=Math.min(section.offsetHeight,Math.max(0,-rect.top))*.16;art.style.transform=`translateY(${travel}px)`}}
addEventListener('scroll',()=>{if(!waterFrame){waterFrame=true;requestAnimationFrame(updateWaterScroll)}},{passive:true});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',updateWaterScroll);



function syncFilterLabels(){const form=$('#offer-filters');if(!form)return;form.querySelectorAll('label').forEach(label=>{const field=label.querySelector('input,select');if(!field)return;label.classList.add('floating-filter');label.classList.toggle('has-value',Boolean(field.value));if(field.type==='text')field.placeholder='';});}

// Optional visual experiment: the original screens remain available through the switch.
function editorialCard(o){const admin=user.role==='admin';return `<article class="editorial-card"><span class="editorial-hover-blur" aria-hidden="true"></span><img src="${esc(window.previewAsset(o.image))}" alt="${esc(o.title)}" loading="lazy"><span class="editorial-age">${o.age_min}–${o.age_max}<small>lat</small></span><div class="editorial-card-copy"><h3>${esc(o.title.replace(o.place+' · ',''))}</h3><p>${icon('pin')}${esc(o.place)} · ${date(o.start_date)}</p><div><strong>${money(o.price)}<small>za uczestnika</small></strong><button ${admin?`data-edit-offer="${o.id}" aria-label="Edytuj wyjazd: ${esc(o.title)}"`:`data-offer="${o.id}" aria-label="Poznaj wyjazd: ${esc(o.title)}"`}>${admin?'Edytuj':o.available?'Zobacz wyjazd':'Brak miejsc'}</button></div>${admin?`<p class="editorial-admin-meta">${o.booked} / ${o.capacity} uczestników · ${o.active?'Opublikowane':'Ukryte'}</p>`:''}</div></article>`}
function editorialHome(){const b=state.bookings[0];return `<section class="home-journey" aria-label="Znajdź Waszą nową przygodę"><div class="editorial-profile"><span class="avatar">${esc(initials(user.name))}</span><div><strong>${esc(user.name)}</strong><span>Twoja przestrzeń Longwave</span></div><img src="assets/brand.png" alt="LONGWAVE"></div><div class="editorial-title"><h1>Znajdź Waszą<br>nową przygodę.</h1><form id="editorial-search" role="search"><label for="editorial-query" class="editorial-sr">Szukaj wyjazdu</label>${icon('search')}<input id="editorial-query" name="q" placeholder="Szukaj…" autocomplete="off"><button aria-label="Wyszukaj wyjazd">${icon('arrow')}</button></form></div><div class="section-heading"><h2>Polecane wyjazdy</h2><button data-go="offers">Zobacz wszystkie</button></div><div class="editorial-rail">${state.offers.slice(0,4).map(editorialCard).join('')}</div></section><section class="home-plans" aria-label="Wasze plany"><div class="section-heading editorial-plans-heading"><h2>Wasze plany</h2><button data-go="bookings">Wszystkie ${icon('up')}</button></div>${b?`<button class="editorial-plan" data-booking="${b.id}"><img src="assets/${esc(state.offers.find(o=>o.id===b.offer_id)?.image||'coast')}.webp" alt=""><span><strong>${esc(b.title)}</strong><small>${esc(b.first_name)} · ${date(b.start_date)}</small></span>${icon('arrow')}</button>`:`<button class="editorial-plan" data-go="people">Dodaj uczestnika i zaplanuj pierwszy wyjazd ${icon('plus')}</button>`}<div class="editorial-footer"><span>Więcej niż wakacje.</span>${icon('wave')}</div></section>`}

function transferDetails(id){const b=state.bookings.find(x=>x.id===id);if(!b)return;const remaining=Math.max(0,b.amount-b.paid),reference=`LW-${String(b.id).padStart(4,'0')} / ${b.first_name} ${b.last_name} / ${b.title}`;openModal(`<div class="modal-body"><span class="eyebrow muted">ZAPIS LW-${String(b.id).padStart(4,'0')}</span><h2>Szczegóły płatności.</h2><p>${esc(b.title)}</p><div class="transfer-amount"><span>${remaining?'Pozostało do wpłaty':'Wyjazd opłacony'}</span><strong>${money(remaining)}</strong></div><dl class="transfer-data"><div><dt>Odbiorca przelewu</dt><dd class="transfer-missing">Do uzupełnienia</dd></div><div><dt>Numer konta</dt><dd class="transfer-missing">Do uzupełnienia</dd></div><div><dt>Tytuł przelewu</dt><dd>${esc(reference)}</dd></div></dl><p class="form-note">Wersja demonstracyjna — nie wykonuj przelewu. Dane konta zostaną uzupełnione przez organizatora.</p><div class="form-actions"><button class="btn ghost" id="payment-back">Wróć do zapisu</button></div></div>`);$('#payment-back').onclick=()=>bookingDetails(id)}

// Premium Web 1.0.0 parallax / motion-accessibility, adapted to vanilla CSS + WAAPI.
let cardFrame=0;
function queueCardParallax(){if(!cardFrame)cardFrame=requestAnimationFrame(updateCardParallax)}
function updateCardParallax(){cardFrame=0;const enabled=motionOK();document.querySelectorAll('.editorial-card').forEach(card=>{if(!enabled){card.style.removeProperty('--photo-shift');return}const r=card.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const progress=Math.max(-1,Math.min(1,(innerHeight/2-r.top-r.height/2)/(innerHeight/2+r.height/2)));card.style.setProperty('--photo-shift',(progress*14).toFixed(2)+'px')})}
addEventListener('scroll',queueCardParallax,{passive:true});addEventListener('resize',queueCardParallax,{passive:true});
const syncCardMotion=()=>{if(!motionOK()){document.getAnimations().forEach(a=>{if(a.effect?.getComputedTiming().iterations===Infinity)a.cancel();else a.finish()});}queueCardParallax()};
matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',syncCardMotion);
new MutationObserver(syncCardMotion).observe(document.body,{attributes:true,attributeFilter:['class']});

// Participant balances and a shared reward catalogue. Requests are persisted by the API.
function rewardsModal(pid){const p=state.participants.find(x=>x.id===pid);if(!p)return;const history=state.redemptions.filter(r=>r.participant_id===pid);openModal(`<div class="modal-body loyalty-modal"><p class="eyebrow">FALKI LONGWAVE</p><h2>${esc(p.first_name)}, czas na nagrody.</h2><div class="falki-balance"><span class="falki-wave" aria-hidden="true">≈</span><div><strong>${p.falki||0}</strong><span>Twoje falki</span></div></div><p>Zdobywasz falki za w pełni opłacone obozy. Wybierz coś dla siebie.</p><div class="reward-list">${state.rewards.filter(r=>r.active).map(r=>`<article class="reward-card"><div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><strong>${r.cost} falek</strong></div><button class="btn" data-redeem="${r.id}" ${(p.falki||0)<r.cost?'disabled':''}>${(p.falki||0)<r.cost?'Brakuje '+(r.cost-(p.falki||0))+' falek':'Wybierz nagrodę'}</button></article>`).join('')||'<p>Nagrody pojawią się wkrótce.</p>'}</div>${history.length?`<h3>Twoje nagrody</h3>${history.map(r=>`<div class="reward-history"><div><strong>${esc(r.title)}</strong><span>${r.cost} falek</span></div><span>${r.status==='fulfilled'?'Wydana':'Do odbioru'}</span></div>`).join('')}`:''}</div>`);$$('[data-redeem]').forEach(b=>b.onclick=()=>redeemConfirm(pid,+b.dataset.redeem))}
function redeemConfirm(pid,rid){const p=state.participants.find(x=>x.id===pid),r=state.rewards.find(x=>x.id===rid),request_id=crypto.randomUUID();openModal(`<div class="modal-body"><p class="eyebrow">WYMIANA FALEK</p><h2>${esc(r.title)}</h2><p>${esc(p.first_name)} wymieni <strong>${r.cost} falek</strong> na tę nagrodę. Po wymianie zostanie ${p.falki-r.cost} falek.</p><form id="redeem-form"><p class="error-box" role="alert"></p><div class="form-actions"><button type="button" class="btn ghost" id="reward-back">Wróć</button><button type="submit" class="btn">Wymień ${r.cost} falek</button></div></form></div>`);$('#reward-back').onclick=()=>rewardsModal(pid);$('#redeem-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await api('redeem',{participant_id:pid,reward_id:rid,request_id});await load();renderPage();rewardsModal(pid);toast('Nagroda zapisana do odbioru.')})}}
function loyaltyAdmin(){openModal(`<div class="modal-body loyalty-modal"><p class="eyebrow">PROGRAM LOJALNOŚCIOWY</p><h2>Falki za przygody.</h2><form id="loyalty-form"><label>Domyślna liczba falek za nowy obóz<input type="number" name="default_falki" min="0" max="10000" required value="${state.default_falki}"></label><p>Wartość dla nowych ofert. Dla konkretnego obozu zmienisz ją w edycji wydarzenia. Falki naliczamy po pełnej wpłacie.</p><p class="error-box" role="alert"></p><button type="submit" class="btn">Zapisz ustawienie</button></form><div class="section-heading"><h3>Katalog nagród</h3><button class="btn" id="add-reward">${icon('plus')} Dodaj nagrodę</button></div><div class="reward-list">${state.rewards.map(r=>`<article class="reward-card"><div><h3>${esc(r.title)}</h3><p>${r.cost} falek · ${r.active?'Dostępna':'Ukryta'}</p></div><button class="btn ghost" data-edit-reward="${r.id}">Edytuj</button></article>`).join('')}</div><h3>Wymiany uczestników</h3>${state.redemptions.map(r=>`<div class="reward-history"><div><strong>${esc(r.title)}</strong><span>${esc(r.first_name+' '+r.last_name)} · ${r.cost} falek</span></div>${r.status==='fulfilled'?'<span>Wydana</span>':`<button class="btn ghost" data-fulfill="${r.id}">Oznacz jako wydaną</button>`}</div>`).join('')||'<p>Nie ma jeszcze wymian.</p>'}<p class="error-box" id="loyalty-error" role="alert"></p></div>`);$('#loyalty-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{await api('admin/loyalty',{default_falki:+new FormData(e.target).get('default_falki')});await load();renderPage();toast('Ustawienie falek zapisane.')})};$('#add-reward').onclick=()=>rewardForm();$$('[data-edit-reward]').forEach(b=>b.onclick=()=>rewardForm(+b.dataset.editReward));$$('[data-fulfill]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('admin/redemptions/'+b.dataset.fulfill,{status:'fulfilled'},'PUT');await load();renderPage();loyaltyAdmin();toast('Nagroda oznaczona jako wydana.')}catch(e){$('#loyalty-error').textContent=e.message;b.disabled=false}})}
function rewardForm(id){const r=state.rewards.find(x=>x.id===id)||{title:'',description:'',cost:100,active:1};openModal(`<div class="modal-body"><h2>${id?'Edytuj nagrodę.':'Nowa nagroda.'}</h2><form id="reward-form"><label>Nazwa nagrody<input name="title" required minlength="2" maxlength="100" value="${esc(r.title)}"></label><label>Opis<textarea name="description" maxlength="500">${esc(r.description)}</textarea></label><label>Koszt w falkach<input type="number" name="cost" min="1" max="100000" required value="${r.cost}"></label><label>Widoczność<select name="active"><option value="1" ${r.active?'selected':''}>Dostępna do wymiany</option><option value="0" ${!r.active?'selected':''}>Ukryta</option></select></label><p class="error-box" role="alert"></p><div class="form-actions"><button type="button" class="btn ghost" id="rewards-back">Wróć</button><button type="submit" class="btn">Zapisz nagrodę</button></div></form></div>`);$('#rewards-back').onclick=loyaltyAdmin;$('#reward-form').onsubmit=e=>{e.preventDefault();busy(e.target,async()=>{const d=Object.fromEntries(new FormData(e.target));await api('admin/rewards'+(id?'/'+id:''),{...d,cost:+d.cost,active:d.active==='1'},id?'PUT':'POST');await load();renderPage();loyaltyAdmin();toast('Nagroda zapisana.')})}}
